const uniq=a=>[...new Set((a||[]).filter(Boolean))];
const add=(id,x)=>{const p=P[id];if(!p)return;p.detail=uniq([...(p.detail||[]),...(x.detail||[])]);p.must=uniq([...(p.must||[]),...(x.must||[])]);p.traps=uniq([...(p.traps||[]),...(x.traps||[])]);if(x.compare)p.compare=[...(p.compare||[]),...x.compare];if(x.flow)p.flow=uniq([...(p.flow||[]),...x.flow]);p.depthEnriched=true;p.status='verified'};

add('F01-C02',{detail:['소방력은 화재·재난 현장에서 임무를 수행하기 위한 인력과 차량·장비, 소방용수를 함께 보는 개념이다. 문제에서는 소방대라는 인력 요소만을 소방력 전체와 동일시하지 말고, 인력·장비·용수의 결합으로 구분해야 한다.'],must:['소방력은 인력만이 아니라 차량·장비와 소방용수를 함께 포함'],traps:['소방대와 소방력 전체를 같은 뜻으로 보지 않는다.'],compare:[['소방대','현장활동 인력 중심'],['소방력','인력 + 차량·장비 + 소방용수의 종합 능력']]});
add('F01-C03',{detail:['소방용수시설은 화재진압에 필요한 용수를 안정적으로 확보하기 위한 시설로 소화전·급수탑·저수조 등이 포함된다. 장비와 용수시설은 설치 자체뿐 아니라 평상시 유지·관리와 실제 현장에서의 사용 가능 상태가 중요하다.'],must:['소방용수시설의 대표 예 = 소화전·급수탑·저수조'],traps:['소방장비와 소방용수시설을 같은 범주로 섞어 외우지 않는다.'],compare:[['소방장비','인명구조·진압·구급 등에 사용하는 기계·기구'],['소방용수시설','화재진압용 물을 확보·공급하는 시설']]});
add('F01-C05',{detail:['의용소방대는 관설 소방업무를 보조하는 비상근 민간소방조직으로, 시·도지사 또는 소방서장이 화재진압·구조·구급·화재예방 활동을 보조하도록 설치할 수 있다. 임무에는 화재 경계·진압 보조, 구조·구급 보조, 재난 시 대피·구호 보조, 화재예방 보조가 포함된다.'],must:['의용소방대 정년 = 65세','설치 주체 = 시·도지사 또는 소방서장','주요 임무 = 화재·구조구급·대피구호·예방 업무 보조'],traps:['의용소방대를 상근 국가소방조직으로 보지 않는다.']});

add('F04-C02',{detail:['좋은 소화약제는 연소의 4요소 중 적어도 하나를 효과적으로 제거·억제할 수 있어야 하며, 가격·저장안정성·환경오염·인체독성도 함께 고려한다. 따라서 소화성능만 강하면 무조건 적합한 약제라고 판단해서는 안 된다.'],must:['소화성능 외에 저장안정성·환경영향·인체독성도 소화약제 조건'],traps:['소화약제의 평가는 단순히 냉각능력 하나만으로 결정하지 않는다.']});
add('F04-C04',{detail:['포 소화약제는 물에 포원액을 섞고 공기를 혼합해 만든 기포가 유류 표면을 덮어 공기 접촉을 차단하는 질식효과와 물에 의한 냉각효과를 동시에 낸다. 현재 일반적으로 말하는 포는 기계적으로 공기를 혼합한 공기포이며, 국내 기준에서는 팽창비 20 이하를 저팽창포, 80 이상을 고팽창포로 구분한다.'],must:['포의 주 소화효과 = 질식 + 냉각','국내 팽창비 기준: 저팽창 20 이하, 고팽창 80 이상'],traps:['포를 전기화재에 물과 동일하게 무조건 적용하는 약제로 생각하지 않는다.']});
add('F04-C05',{detail:['이산화탄소는 공기보다 약 1.5배 무겁고 전기적으로 비전도성이며 잔사가 남지 않는다. 주효과는 산소농도를 낮추는 질식이고 일부 냉각효과가 있으며, 보통 B·C급에 사용하고 밀폐된 A급에도 적용할 수 있다. 최소 설계농도는 일반적으로 34vol% 이상으로 설명되며 인명 질식 위험 때문에 밀폐된 유인공간 사용에는 주의가 필요하다.'],must:['CO₂ 주효과 = 질식, 보조효과 = 냉각','주 적응 = B·C급, 밀폐 A급 가능','일반적 최소 설계농도 34vol% 이상'],traps:['CO₂는 잔사가 없지만 인체에 안전한 약제라는 뜻은 아니다. 산소저하로 질식 위험이 있다.']});
add('F04-C06',{detail:['할론은 탄화수소의 수소 일부 또는 전부가 할로겐 원소로 치환된 화합물로, 연소 연쇄반응을 억제하는 화학적 소화효과가 핵심이다. 주로 B·C급에 적합하고 밀폐 전역방출에서는 A급에도 사용할 수 있으며 잔사가 거의 없어 전기·통신 설비에 유리하지만 오존층 파괴 문제로 생산·사용이 국제적으로 규제되어 대체약제가 개발되었다.'],must:['할론 주효과 = 연쇄반응 억제(부촉매/억제소화)','주 적응 = B·C급, 밀폐 A급 가능','오존층 파괴 때문에 국제 규제 대상'],traps:['할론의 주효과를 CO₂처럼 단순 질식소화로 외우지 않는다.']});
add('F04-C07',{detail:['할론 대체용 할로겐화합물·불활성기체 약제는 전기적으로 비전도성이며 증발 후 잔류물을 거의 남기지 않는 가스계 약제다. 불활성기체 계열은 산소농도를 낮추는 방식이 중심이며, 대표적으로 IG-01은 Ar, IG-100은 N₂, IG-55는 N₂ 50%+Ar 50%, IG-541은 N₂ 52%+Ar 40%+CO₂ 8%로 구성된다.'],must:['IG-541 = N₂ 52% + Ar 40% + CO₂ 8%','IG-55 = N₂ 50% + Ar 50%','IG-01 = Ar, IG-100 = N₂'],traps:['불활성기체 약제와 할론의 화학적 연쇄반응 억제기전을 같은 것으로 보지 않는다.']});

add('E03-C01',{detail:['감염예방은 환자의 진단명이나 감염 여부를 알고 있는지와 관계없이 모든 환자 처치에 적용하는 기본 원칙이다. 혈액뿐 아니라 체액·분비물 등으로 감염원이 전파될 수 있다고 보고 장갑·마스크·보안경·가운 등 개인보호장비를 상황에 맞게 사용한다.'],must:['감염예방은 모든 환자에게 적용','혈액뿐 아니라 체액·분비물도 전파원으로 고려'],traps:['감염 확진 환자에게만 개인보호장비를 착용한다고 생각하지 않는다.']});
add('E06-C01',{detail:['환자 이동 전에는 먼저 필요한 자세, 이동경로, 구출방법과 사용할 장비를 계획하고 환자의 체중·주변 장애물·필요 인원을 판단한다. 원칙적으로 이동 전에 1차 평가와 필요한 처치를 시행하고 충분히 고정하지만, 현장 자체가 위험하거나 즉시 이동하지 않으면 생명이 위협되는 경우에는 긴급이동을 우선할 수 있다.'],must:['이동 전 계획 = 자세·경로·장비·인원 판단','원칙적으로 1차 평가와 필요한 처치 후 이동'],traps:['대원 수가 부족한데도 무리하게 환자를 들어 올리지 않는다.']});
add('E06-C05',{detail:['환자 자세는 의식·호흡·순환·구토·손상부위·마비·통증 등을 종합해 결정한다. 머리·척추손상이 없는 무의식 환자는 좌측위 또는 회복자세가 기도 분비물 배출에 유리하고, 호흡곤란이나 가슴통증 환자는 일반적으로 환자가 편안해하는 좌위·앉은 자세를 취하게 한다.'],must:['무의식 + 척추손상 없음 → 회복자세/좌측위 고려','호흡곤란·가슴통증 → 편안한 좌위/앉은 자세 고려'],traps:['모든 환자에게 같은 이송 자세를 적용하지 않는다.']});
add('E07-C03',{detail:['순환유지 장비에는 기계식 가슴압박 장치와 자동심장충격기 등이 포함된다. AED는 심실세동과 무맥성 심실빈맥 같은 제세동 가능한 리듬을 분석해 충격 여부를 안내하며, 충격 후에는 즉시 약 2분간 심폐소생술을 재개하고 주기적으로 리듬을 다시 분석한다.'],must:['AED 충격 후 즉시 약 2분 CPR 재개','AED는 제세동 가능 리듬을 분석해 충격을 안내'],traps:['AED 분석 중 환자와 계속 접촉하거나 가슴압박을 이어가지 않는다.']});
add('E07-C04',{detail:['환자이송 장비는 환자 상태와 공간에 맞춰 선택한다. 주들것은 바퀴와 상체 각도 조절이 가능하지만 전복 위험을 주의하고, 분리형 들것은 환자 움직임을 줄여 바닥에서 옮기기 좋다. 바구니형은 수직·수평 구조, 가변형은 좁은 공간, 계단형은 계단 이송에 유용하지만 각 장비의 척추고정 가능 여부를 구분해야 한다.'],must:['장비 선택은 환자 상태·공간·이동경로에 따라 달라짐','계단형·가변형 들것은 단독 척추고정에 적합하지 않음'],traps:['들것 이름만 외우지 말고 척추고정 가능 여부와 사용환경을 함께 구분한다.']});
add('E07-C05',{detail:['외상처치 장비의 목보호대는 경추고정의 시작이지만 목보호대 하나만으로 완전한 척추고정이 되는 것은 아니다. 머리고정장비와 긴 척추고정판을 함께 사용하고 환자 크기에 맞는 보호대를 선택한다. 철사부목·패드부목·공기부목 등은 손상부위와 형태에 맞게 선택한다.'],must:['목보호대 단독 = 완전한 경추고정 아님','환자 크기에 맞는 목보호대 선택'],traps:['목보호대를 착용했다고 머리·몸통 고정을 생략하지 않는다.']});

add('E08-C01',{detail:['현장 확인은 환자에게 닿기 전부터 시작한다. 출동정보로 환자 수·사고유형·위험물·구조 필요성을 파악하고, 도착 후에는 전선·연료누출·폭력·교통·기상·위험물 등 대원과 환자를 위협하는 요소를 확인한다. 안전하지 않으면 무리하게 진입하지 않고 안전지대에서 추가 지원을 요청한다.'],must:['대원 안전이 환자 접근보다 우선','위험현장은 교육·장비가 없으면 안전지대에서 추가 지원 요청'],traps:['환자가 보인다는 이유로 현장안전 확인을 생략하지 않는다.']});
add('E08-C03',{detail:['2차 평가는 1차 평가 후 병력과 생체징후를 더 자세히 수집하는 단계다. SAMPLE 형식으로 현재 증상·알레르기·약물·과거력·마지막 섭취·사건경위를 확인하고, 맥박·혈압·호흡·피부상태 등 최초 생체징후를 기준값으로 남겨 이후 재평가 결과와 비교한다.'],must:['2차 평가 핵심 = SAMPLE 병력 + 생체징후','최초 생체징후는 재평가 비교 기준'],traps:['2차 평가를 1차 평가보다 먼저 시행하지 않는다.']});
add('E08-C06',{detail:['재평가는 한 번의 평가로 끝내지 않고 상태 변화와 처치 효과를 반복 확인하는 과정이다. AVPU, 기도·호흡·맥박·피부·모세혈관 재충혈, 통증과 손상, 생체징후를 다시 확인하고 갑작스러운 상태 변화가 있으면 예정된 시간과 관계없이 즉시 재평가한다. 교재 기준으로 위급 환자는 5분, 그 외 환자는 15분 간격이 기본이다.'],must:['위급 환자 재평가 5분 간격','그 외 환자 재평가 15분 간격','갑작스런 변화 시 즉시 재평가'],traps:['재평가를 단순히 혈압만 다시 재는 단계로 축소하지 않는다.']});
add('E09-C01',{detail:['기도유지는 1차 평가에서 가장 먼저 해결해야 할 생명위협 문제 중 하나다. 의식이 떨어지면 턱과 혀 근육이 이완되어 혀가 뒤로 떨어져 상기도를 막을 수 있으므로, 환자가 말하거나 울 수 있는지 확인하고 필요하면 즉시 기도개방·흡인·보조기구를 적용한다.'],must:['기도가 열리지 않으면 효과적인 호흡·환기도 불가능','무의식 환자에서 혀에 의한 기도폐쇄 주의'],traps:['호흡수만 보고 기도개방 여부를 확인했다고 판단하지 않는다.']});

add('E10-C02',{detail:['정상 호흡은 연령에 맞는 횟수뿐 아니라 규칙성, 충분한 깊이, 좌우 대칭 가슴상승, 정상 호흡음, 보조근 미사용을 함께 만족해야 한다. 교재 기준 정상 호흡수는 성인 12~20회/분, 소아 15~30회/분, 영아 25~50회/분이며 비정상 호흡은 수치와 호흡노력·음·피부색을 함께 평가한다.'],must:['성인 12~20회/분·소아 15~30회/분·영아 25~50회/분(교재 기준)','호흡수 + 깊이 + 규칙성 + 흉곽상승 + 호흡노력을 함께 평가'],traps:['호흡수가 정상 범위라는 이유만으로 정상 호흡이라고 단정하지 않는다.']});
add('E10-C05',{detail:['연기흡입 손상은 산소 부족과 자극성 연기, 독성 연소생성물, 뜨거운 기체에 의한 열손상이 함께 기도를 위협할 수 있다. 얼굴 그을음·콧털 그을림·쉰목소리·기침·천명·상기도 부종을 관찰하고 안전한 곳으로 이동시킨 뒤 고농도 산소와 환기 보조를 준비하며 신속히 이송한다.'],must:['연기흡입 = 저산소 + 독성/자극물 + 열손상 고려','쉰목소리·그을음·천명·상기도 부종은 기도위험 징후'],traps:['겉에 화상이 없다는 이유로 흡입손상을 배제하지 않는다.']});
add('E11-C05',{detail:['심장충격기는 심실세동처럼 무질서한 전기활동으로 유효한 심박출이 없는 상태와 무맥성 심실빈맥에서 제세동을 시행한다. 빠른 제세동이 중요하지만 모든 빈맥에 충격하는 것은 아니며, 심실빈맥도 맥박이 없을 때 제세동 대상이 된다. AED는 리듬 분석을 자동화해 현장 사용을 돕는다.'],must:['제세동 대표 리듬 = 심실세동·무맥성 심실빈맥','심실빈맥이라도 맥박이 있으면 무조건 제세동하는 것이 아님'],traps:['AED가 모든 심정지 리듬에 충격을 권고한다고 생각하지 않는다.']});

add('E12-C01',{detail:['복강은 가로막 아래에서 골반까지 이어지며 소화계뿐 아니라 비뇨·생식·내분비 관련 장기도 포함한다. 위는 음식 저장·소화, 소장은 영양흡수, 대장은 수분흡수와 대변 형성, 간은 대사·해독·담즙 생성, 췌장은 소화효소와 인슐린, 콩팥은 혈액여과와 수분·전해질 조절을 담당한다.'],must:['복부 장기는 소화기관만으로 구성되지 않음','간·췌장·콩팥의 핵심 기능을 구분'],traps:['복통의 원인을 위·장 질환으로만 한정하지 않는다.']});
add('E13-C01',{detail:['순환계는 심장·혈관·혈액의 세 요소로 구성되고 산소와 영양분을 조직에 전달하며 대사 노폐물을 회수하는 관류를 유지한다. 동맥은 심장에서 나가는 고압 혈류, 모세혈관은 물질교환, 정맥은 저압으로 심장으로 되돌아오는 혈류를 담당한다. 성인 혈액량은 교재상 약 70mL/kg으로 설명된다.'],must:['순환계 3요소 = 심장·혈관·혈액','동맥=심장에서 나감·정맥=심장으로 돌아옴·모세혈관=물질교환'],traps:['동맥·정맥을 산소량만으로 정의하지 않는다. 방향이 기본 구분이다.']});

add('E14-C01',{detail:['피부는 외부 손상과 감염을 막고 체액 손실을 줄이며 체온조절과 내부조직 보호에 관여한다. 구조는 표피·진피·피하조직으로 나뉘며, 넓은 피부손상은 단순 상처를 넘어 감염·체액손실·체온조절 장애로 이어질 수 있다.'],must:['피부 주요 기능 = 보호·감염방어·체액보존·체온조절','피부 구조 = 표피·진피·피하조직'],traps:['피부손상을 출혈 문제로만 평가하지 않는다.']});
add('E14-C02',{detail:['연부조직 손상은 폐쇄성과 개방성으로 나눌 수 있다. 폐쇄성에는 타박상·혈종·압궤손상 등이, 개방성에는 찰과상·열상·박리·절단·관통상 등이 포함된다. 관통상은 겉 상처가 작아도 내부 장기와 혈관에 큰 손상이 있을 수 있으므로 손상기전과 출혈·쇼크를 함께 평가한다.'],must:['폐쇄성 손상과 개방성 손상 유형 구분','관통상은 작은 외부상처보다 내부손상이 클 수 있음'],traps:['상처 크기가 작다는 이유로 관통상을 경미하다고 판단하지 않는다.']});
add('E14-C03',{detail:['화상 깊이는 1도·2도·3도 화상으로 구분하며 면적은 성인에서 9의 법칙을 사용할 수 있고 작은 화상은 환자 손바닥 면적을 약 1%로 볼 수 있다. 기도화상 징후가 있으면 기도를 우선하고, 장신구·조이는 물품을 제거하며 건조한 멸균드레싱으로 보호하고 물집을 터뜨리거나 연고를 임의로 바르지 않는다.'],must:['작은 화상 면적: 환자 손바닥 ≈ 1%','기도화상 의심 시 기도·산소가 우선','물집을 임의로 터뜨리지 않음'],traps:['화상면적 계산보다 기도손상 평가를 뒤로 미루지 않는다.']});
add('E15-C03',{detail:['부목은 손상부위 움직임을 줄여 통증과 추가 혈관·신경·연부조직 손상을 예방한다. 고정 전후에는 손상부위 먼쪽의 맥박·운동·감각(PMS)을 확인하고, 너무 느슨하면 고정효과가 없고 너무 조이면 순환을 방해할 수 있다. 생명위협 문제가 있으면 부목 때문에 이송을 지연하지 않는다.'],must:['부목 전후 PMS 확인','너무 느슨하거나 너무 조인 부목 모두 문제','ABC 위급상황이면 부목보다 생명유지·이송 우선'],traps:['변형을 교정하려고 무리하게 팔다리를 당기지 않는다.']});

add('E16-C02',{detail:['척수손상은 손상부위 아래의 운동·감각 기능을 잃게 하고 높은 목뼈 손상은 호흡근 마비로 생명을 위협할 수 있다. 손상기전에는 굴곡·신전·측면굽힘·회전·압박·분리·관통이 있으며, 환자가 걷고 있거나 척추 압통이 없다고 해서 손상을 배제하지 않는다. 수기 머리고정과 ABC 처치를 동시에 시행하고 PMS를 반복 확인한다.'],must:['경추손상은 호흡근까지 영향 가능','걷는 환자도 척추손상 배제 불가','척추손상 확인을 위해 일부러 목·허리를 움직이지 않음'],traps:['목보호대만 착용하면 척추고정이 끝났다고 생각하지 않는다.']});
add('E16-C03',{detail:['머리손상은 두피·머리뼈·뇌 손상을 함께 고려한다. 귀·코의 혈액 또는 맑은 액체, 눈 주위 반상출혈, 귀 뒤 반상출혈, 머리뼈 변형, 의식변화·구토·비대칭 동공·경련은 중요한 징후다. 목뼈손상을 함께 가정하고 턱밀어올리기로 기도를 유지하며, 교재는 두개내압 상승 징후가 있으면 상체 30~45도 거상과 흡인 준비를 제시한다.'],must:['머리손상에서 의식수준 변화 반복 평가','귀·코의 맑은 액체·너구리눈·Battle sign 주의','Cushing 징후 = 고혈압·서맥·불규칙 호흡'],traps:['처음 의식이 정상이라고 지연성 뇌손상을 배제하지 않는다.']});
add('E18-C02',{detail:['알레르기 반응은 과도한 면역반응으로 피부 증상만이 아니라 얼굴·혀·상기도 부종, 기관지 수축, 저혈압·쇼크까지 진행할 수 있다. 기도와 호흡을 먼저 평가하고 원인 노출과 과거력을 확인하며, 호흡곤란이나 쇼크에서는 고농도 산소·환기 보조를 준비하고 의료지시에 따른 에피네프린 사용을 고려한다.'],must:['아나필락시스에서 기도·호흡이 최우선','얼굴·혀 부종 + 호흡곤란 + 저혈압은 중증 신호'],traps:['두드러기가 없다고 중증 알레르기 반응을 배제하지 않는다.']});

add('E19-C01',{detail:['인체는 중심체온을 약 37℃로 유지하려고 열생산과 열손실을 조절한다. 열은 복사·전도·대류·증발 등으로 이동하며, 특히 물에서는 공기보다 열전도가 훨씬 빨라 같은 온도라도 저체온이 더 빠르게 진행될 수 있다. 환경응급 평가에서는 노출시간·습기·바람·환자 연령과 기저질환을 함께 본다.'],must:['중심체온 정상 목표 약 37℃','열손실 기전 = 복사·전도·대류·증발','물에서는 공기보다 열손실이 매우 빠름'],traps:['기온만 보고 한랭·열 손상 위험을 판단하지 않는다.']});
add('E19-C05',{detail:['벌쏘임은 침이 남아 있으면 카드 모서리처럼 긁어 제거하고 핀셋으로 짜서 독주머니를 더 압박하지 않도록 하며, 전신 알레르기 징후를 관찰한다. 뱀교상은 환자를 안정시키고 장신구를 제거하며 손상부위를 심장보다 낮게 고정해 이송하고, 절개·흡인·전기충격·얼음 같은 처치는 하지 않는다.'],must:['벌침은 짜기보다 긁어 제거','뱀교상은 안정·고정·신속 이송','뱀교상 절개·흡인·전기충격·얼음 금지'],traps:['뱀교상에 일반 지혈대를 강하게 적용하지 않는다.']});

add('E20-C02',{detail:['분만은 1기 자궁수축 시작부터 자궁경부 완전개대 10cm까지, 2기 태아가 산도를 지나 출생할 때까지, 3기 태반과 제대·양막 등이 만출될 때까지로 나뉜다. 수축이 잦아지고 배림이 보이거나 대변을 보고 싶은 느낌을 호소하면 분만 임박 가능성을 높게 보며 현장분만과 이송 여부를 판단한다.'],must:['분만 1기 = 경부 완전개대 10cm까지','2기 = 태아 만출까지','3기 = 태반 만출까지','배림이 보이면 즉시 분만 준비'],traps:['분만 임박 산모를 화장실에 보내지 않는다.']});
add('E20-C04',{detail:['제대탈출은 태아보다 제대가 먼저 나와 압박되면서 태아 산소공급이 차단되는 응급상황이다. 산모 골반을 올리고 머리를 낮추며 고농도 산소를 주고, 멸균 장갑으로 태아 선진부를 들어 제대 압박을 줄이되 제대를 안으로 밀어 넣지 않는다. 둔위·사지 선진에서는 태아를 잡아당기지 말고 고농도 산소와 신속 이송을 우선한다.'],must:['제대탈출 → 골반 올림·고농도 산소·제대 압박 완화·신속 이송','노출 제대는 따뜻한 멸균 젖은 거즈로 보호','둔위에서 태아 다리를 잡아당기지 않음'],traps:['제대탈출 시 제대를 질 안으로 밀어 넣지 않는다.']});
add('E20-C05',{detail:['임신 중 응급상황에서는 산모의 ABC와 태아 상태를 함께 고려한다. 임신 20주 이내 출혈·복통은 자연유산 가능성을 보고 조직을 보존해 병원에 인계하며, 임신후기 경련은 자간증 가능성을 고려해 기도·산소·흡인을 준비하고 좌측위로 이송한다. 후기 질출혈은 전치태반·태반박리 가능성이 있어 질 안에 거즈를 넣지 않고 즉시 이송한다.'],must:['자연유산 교재 정의 = 임신 20주 이내','임신 중 경련 → 기도·산소·흡인 준비, 좌측위 이송','후기 질출혈 → 질내 패킹 금지·신속 이송'],traps:['태아 걱정 때문에 산모의 ABC 처치를 지연하지 않는다.']});
add('E21-C05',{detail:['소아평가는 성인과 마찬가지로 현장 확인과 1차 평가가 우선이지만, 일반적 인상에서 피부색·울음/말소리·주변과 부모에 대한 반응·정서·자세와 근긴장을 빠르게 본다. 의식은 AVPU로 확인하고 호흡수·맥박·혈압은 연령별 정상 범위와 비교하며, 좌우 흉곽상승과 호흡노력도 함께 기록한다.'],must:['소아 일반적 인상 = 피부색·울음/말·상호작용·자세/근긴장','AVPU 사용','생체징후는 연령별 정상범위와 비교'],traps:['소아를 성인의 정상 활력징후 기준으로 평가하지 않는다.']});

add('E22-C02',{detail:['노인환자는 독립성 상실과 입원에 대한 두려움, 자존감 문제로 응급상황에 다르게 반응할 수 있다. 가족에게만 묻기보다 환자 본인에게 직접 말하고 눈높이를 맞추며 천천히 분명하게 설명한다. 시력·청력 저하가 있더라도 무조건 큰소리로 말하기보다 보청기·안경 사용 여부와 이해 정도를 확인한다.'],must:['노인에게도 환자 본인에게 직접 설명·질문','눈높이를 맞추고 충분한 반응시간 제공'],traps:['반응이 느리다는 이유로 인지능력이 없다고 단정하지 않는다.']});
add('E22-C03',{detail:['노인도 기도·호흡·순환·의식·우선순위라는 기본 평가 순서는 동일하지만 만성질환, 여러 처방약, 감각저하와 만성 의식변화 때문에 더 세밀한 평가가 필요하다. 낙상은 단순 사고로만 보지 말고 부정맥·실신 같은 선행 의학적 원인이 있었는지 확인하며 최근 의식변화가 기존 상태인지 새로 생긴 것인지 보호자 정보와 비교한다.'],must:['평가 우선순위는 연령과 관계없이 ABC 중심','다약제·만성질환·기존 인지상태 확인','낙상의 원인 사건도 평가'],traps:['노인의 혼돈을 모두 노화의 정상 현상으로 넘기지 않는다.']});
add('E23-C02',{detail:['자살위험 환자는 현장안전을 먼저 확보하고 절망감·최근 스트레스와 상실·술/약물 사용·구체적 계획·과거 시도력을 평가한다. 안전하다면 환자를 혼자 두지 않고 대화를 지속한다. 공격적 환자에서는 탈출로를 확보하고 혼자 대치하지 않으며 무기 가능 장소를 피하고 필요하면 현장에서 이탈해 경찰 지원을 기다린다.'],must:['자살위험 = 계획·과거시도·최근 상실·약물/알코올 등 평가','공격적 환자 = 탈출로 확보·혼자 대치 금지·경찰 협조'],traps:['대원의 안전이 확보되지 않은 상태에서 설득을 위해 무리하게 접근하지 않는다.']});
add('E23-C03',{detail:['행동응급 기록은 환자의 행동을 평가자의 주관적 판단이 아니라 실제 관찰 사실과 환자 발언 중심으로 전문적이고 명확하게 남긴다. 현장상황, 약물·알코올 관련 정보, 경찰관·목격자·협력자 이름을 함께 기록하고, 제지가 있었다면 제지 이유·방법과 제지 부위의 순환상태 관찰도 문서화한다.'],must:['관찰 사실과 환자 발언을 객관적으로 기록','약물·알코올·현장·경찰/목격자 정보 기록','제지 시 이유·방법·순환상태 기록'],traps:['“이상함·미쳤음” 같은 판단적 표현으로 기록하지 않는다.']});

