const put=(id,x)=>{P[id]={status:'scope-verified',compare:[],flow:[],must:[],traps:[],...x,detail:(x.detail||[]),deepSections:x.deepSections||[],sourcePrecision:x.sourcePrecision||'official-scope-pending-page-anchor'}};
const sec=(title,body,bullets=[])=>({title,body,bullets});

put('F05-C01',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'「위험물안전관리법」에서 위험물은 인화성 또는 발화성 등의 성질을 가지는 것으로서 대통령령이 정하는 물품을 말하며, 시행령 별표 1에서 제1류부터 제6류까지 품명과 지정수량을 정한다.',detail:['위험물은 제1류 산화성고체, 제2류 가연성고체, 제3류 자연발화성물질 및 금수성물질, 제4류 인화성액체, 제5류 자기반응성물질, 제6류 산화성액체로 구분한다.','지정수량은 위험물의 종류별 위험성을 고려해 대통령령으로 정한 수량이며 제조소·저장소·취급소의 설치허가 등에서 최저 기준이 되는 수량이다.','특수가연물은 위험물안전관리법의 제1류~제6류 분류가 아니라 「화재의 예방 및 안전관리에 관한 법률」 체계에서 별도로 정하는 가연물 기준이므로 구분해야 한다.'],must:['1류 산화성고체','2류 가연성고체','3류 자연발화성·금수성','4류 인화성액체','5류 자기반응성','6류 산화성액체','지정수량은 품명별 위험성에 따라 정한 법적 기준수량'],traps:['특수가연물을 위험물 제7류처럼 취급하지 않는다.','류만 보고 물 사용 가능·금지를 일률적으로 판단하지 않는다.','지정수량과 특수가연물의 기준수량을 같은 개념으로 혼동하지 않는다.'],source:'위험물안전관리법 제2조 · 위험물안전관리법 시행령 별표 1 · 2026 예방실무2 PDF 345·385쪽',officialLinks:[{label:'국가법령정보센터 위험물안전관리법 제2조',url:'https://www.law.go.kr/LSW/lsLinkCommonInfo.do?lsJoLnkSeq=1033761137'}],deepSections:[sec('법적 정의','위험물안전관리법은 인화성 또는 발화성 등의 성질을 가지며 대통령령이 정하는 물품을 위험물로 정의한다.'),sec('류별 분류와 지정수량','시행령 별표 1에서 위험물을 제1류부터 제6류까지 구분하고 각 품명별 지정수량을 정한다. 지정수량은 저장·취급 규제와 제조소등 설치허가 판단의 기본 수량기준이다.'),sec('특수가연물과의 구분','특수가연물은 화재예방법 체계의 별도 개념이다. 위험물의 류별 지정수량과 특수가연물의 품명별 기준수량은 적용 법령과 기준이 다르다.'),sec('지정수량과 저장 규제의 연결','위험물안전관리법 시행령 제3조는 별표 1의 위험물별 수량을 지정수량으로 정하고, 같은 시행령 제4조는 지정수량 이상의 위험물을 저장하기 위한 장소와 저장소의 구분을 별표 2로 정한다. 따라서 시험에서는 품명·지정수량·저장소 구분을 서로 연결하되 특수가연물 기준과 섞지 않아야 한다.')]});
put('F05-C02',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제1류 위험물은 산화성고체로서 자체가 잘 타기보다 다른 물질의 연소를 강하게 도울 수 있다는 점이 핵심이다.',detail:['가연물·환원성 물질과 접촉하면 연소가 급격히 진행될 수 있어 혼촉 위험을 중요하게 본다.','가열·충격·오염 등으로 분해가 촉진될 수 있으므로 물질별 성상을 확인해 대응해야 한다.'],must:['산화성고체','가연물과의 혼촉 위험','물질별 예외 확인'],traps:['제1류를 일반 가연성 고체로 분류하지 않는다.'],source:'2026 예방실무2 PDF 385쪽',deepSections:[sec('핵심원리','연료 역할보다 산소공급·산화 촉진 역할을 이해하면 다른 류와 구분하기 쉽다.'),sec('현장판단','주변 가연물과 분리하고 열·오염·혼촉 가능성을 먼저 확인한다.')]});
put('F05-C03',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제2류 위험물은 가연성고체로서 불꽃·열에 의해 연소하기 쉽고 일부 금속분 등은 소화방법 선택에 주의해야 한다.',detail:['고체 가연물이라도 입자가 미세할수록 표면적이 커져 연소가 빨라질 수 있다.','금속분 등은 물과의 반응 가능성을 확인해야 하므로 일반 고체화재와 같은 방식으로 단정하지 않는다.'],must:['가연성고체','미세분말의 빠른 연소 가능성','금속분의 물 반응성 주의'],traps:['모든 제2류에 물을 일률적으로 적용한다고 외우지 않는다.'],source:'2026 예방실무2 PDF 407쪽',deepSections:[sec('왜 위험한가','표면적·점화원·분진 상태가 연소속도에 영향을 준다.'),sec('문제풀이','가연성고체라는 공통점과 품목별 금수성 여부를 분리해서 본다.')]});
put('F05-C04',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제3류는 자연발화성 또는 금수성 물질로, 공기 또는 물과의 접촉 자체가 위험요인이 될 수 있다.',detail:['자연발화성 물질은 공기 중에서 스스로 발열·발화할 수 있고, 금수성 물질은 물과 접촉해 가연성가스나 열을 발생시킬 수 있다.','따라서 물을 사용하는 일반적인 냉각소화가 오히려 위험을 키울 수 있어 물질 식별이 우선이다.'],must:['자연발화성','금수성','물질 확인 전 물 사용 주의'],traps:['제3류 화재에 무조건 물을 방사하는 선택지를 경계한다.'],source:'2026 예방실무2 PDF 428쪽',deepSections:[sec('핵심구분','공기와의 반응 위험인지, 물과의 반응 위험인지 구분한다.'),sec('현장판단','누출물의 정체를 확인하기 전 물과 접촉시키지 않는 보수적 접근이 중요하다.')]});
put('F05-C05',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제4류는 인화성액체로, 액면에서 발생한 증기가 공기와 혼합되어 점화되는 구조를 이해해야 한다.',detail:['액체 자체보다 증기의 발생과 확산, 점화원 접촉이 화재위험의 핵심이다.','유면화재에서는 포 등으로 증기 발생과 산소접촉을 억제하는 개념이 중요하며, 직접적인 물줄기가 액체를 퍼뜨릴 수 있는 상황도 고려한다.'],must:['인화성액체','증기-공기 혼합','유면 피복·증기억제'],traps:['액체 자체가 기체 없이 바로 타는 것으로 설명한 선지에 주의한다.'],source:'2026 예방실무2 PDF 449쪽',deepSections:[sec('연소 메커니즘','인화성액체는 표면에서 증발한 증기가 연소한다는 점이 핵심이다.'),sec('소화 연결','냉각뿐 아니라 증기 발생 억제와 액면 피복을 함께 생각한다.')]});
put('F05-C06',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제5류는 자기반응성물질로서 자체 분해반응이 빠르게 진행되며 열·충격 등에 의해 폭발적 반응으로 이어질 수 있다.',detail:['외부에서 산소를 계속 공급하지 않아도 분해반응이 지속될 수 있는 물질이 있어 일반적인 질식만으로 충분하지 않을 수 있다.','가열·충격·마찰 등에 민감할 수 있으므로 물질의 안정성과 분해특성을 함께 본다.'],must:['자기반응성','열·충격·마찰 주의','급격한 분해 가능성'],traps:['산소를 차단하면 모든 제5류 반응이 즉시 멈춘다고 단정하지 않는다.'],source:'2026 예방실무2 PDF 496쪽',deepSections:[sec('핵심원리','자체 분해에 필요한 반응성이 물질 내부에 존재할 수 있다는 점이 다른 가연물과 다르다.'),sec('현장판단','가열된 용기·밀폐공간·충격 가능성을 함께 평가한다.')]});
put('F05-C07',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제6류는 산화성액체로서 강한 산화작용으로 다른 가연물의 연소를 촉진할 수 있다.',detail:['자체가 연료라기보다 산화제로 작용하는 성격이 중요하다.','가연성·환원성 물질과 혼촉될 경우 강한 반응이 일어날 수 있으므로 누출물의 격리와 혼촉 방지가 중요하다.'],must:['산화성액체','혼촉 위험','가연물·환원성물질과 분리'],traps:['제6류를 인화성액체인 제4류와 혼동하지 않는다.'],source:'2026 예방실무2 PDF 523쪽',deepSections:[sec('제4류와 비교','제4류는 연료가 되는 인화성액체, 제6류는 산화를 촉진하는 산화성액체라는 구분이 핵심이다.')]});
put('F05-C08',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'위험물화재는 류별 성상뿐 아니라 보일오버 같은 특수현상과 저장·용기 상태를 함께 판단해야 한다.',detail:['유류 탱크화재에서는 열이 액면 아래로 전달되어 수분층이 급격히 기화하면서 연소 중인 유류가 넘쳐 분출되는 보일오버 위험을 고려한다.','위험물 대응은 물질 식별 → 용기·누출 상태 → 점화원 → 물과의 반응성 → 적합한 소화수단 순으로 판단하는 것이 안전하다.'],must:['보일오버 개념','물질 식별 우선','류별·품목별 소화방법 확인'],traps:['위험물이라는 이유만으로 모든 화재에 같은 소화약제를 적용하지 않는다.'],source:'2026 소방전술1 PDF 319쪽 · 예방실무2 PDF 536쪽',deepSections:[sec('보일오버','탱크 내부 수분의 급격한 기화와 뜨거운 유류의 분출 위험을 연결한다.'),sec('현장 의사결정','물질명·UN 정보·용기상태·누출범위·배수 방향까지 함께 본다.')]});

put('F06-C01',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'화재조사는 화재의 원인과 피해상황을 과학적·객관적으로 규명해 재발방지와 제도개선에 활용하는 활동이다.',detail:['현장에 남은 흔적은 진압·구조·철거 과정에서 쉽게 변형되므로 조사 가능한 상태를 보존하는 것이 중요하다.','원인조사와 피해조사는 서로 연결되지만 목적과 기록 항목을 구분해 이해한다.'],must:['객관적 사실기록','원인 규명','피해 조사','재발방지 활용'],traps:['추정만으로 원인을 확정하거나 현장 흔적을 임의로 훼손하지 않는다.'],source:'2026 소방전술1(화재2) PDF 269·270쪽',deepSections:[sec('왜 필요한가','원인 규명은 책임판단뿐 아니라 예방정책·소방시설 개선·교육에 활용된다.')]});
