put('F03-C09',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'플래시오버는 구획실 전체의 가연물이 축적된 열·복사에 의해 거의 동시에 발화하는 급격한 화재전이 현상이다.',detail:['화재가 성장하면서 천장부 고온 연기층이 두꺼워지고 주변 표면이 강한 복사열을 받으면 아직 직접 화염에 닿지 않은 가연물에서도 열분해가 진행된다.','공간 내 여러 가연물이 발화온도에 가까워지면 화재가 국부 연소에서 구획실 전반의 연소로 급격히 전이될 수 있다.','플래시오버는 산소 유입에 의해 폭발적으로 점화되는 백드래프트와 구분해야 하며, 시험에서는 원인·전조·발생단계를 섞어 출제하기 쉽다.'],must:['열·복사 축적','다수 가연물의 거의 동시 발화','성장기에서 최성기로 급격 전이'],traps:['플래시오버를 산소부족 공간에 공기 유입으로 생기는 현상으로 설명하면 백드래프트와 혼동한 것','플래시오버를 반드시 폭발로 분류하는 선지는 주의'],compare:[['플래시오버','열 축적·복사열·구획실 다수 가연물 동시발화'],['백드래프트','산소부족·미연소가스 축적·공기 유입'],['롤오버','상층 가연성가스의 화염 전파·플래시오버 전조']],flow:['국부화재','고온 연기층 형성','복사열 증가','가연물 열분해','동시발화'],visuals:['flashover-flow'],source:'2026 소방전술1 PDF 37쪽',deepSections:[sec('발생 메커니즘','천장부 고온가스층이 두꺼워질수록 복사열이 실내 가연물 표면을 가열하고 열분해를 촉진한다. 이 상태가 누적되어 다수 가연물이 발화조건에 도달하면 전체 공간이 짧은 시간에 화염에 휩싸일 수 있다.'),sec('전조를 읽는 법','고온·농연·연기층 하강·상층 화염 진행·복사열 증가를 하나의 연속된 위험신호로 본다. 전조 하나만으로 단정하기보다 공간 전체의 열·연기 변화를 종합한다.'),sec('현장 대응 사고','진입대원은 열과 연기층 변화를 지속 관찰하고 급격한 화재전이가 예상되면 진입 깊이·퇴로·냉각·환기 영향을 함께 고려해야 한다.'),sec('시험 포인트','플래시오버는 열 지배 현상, 백드래프트는 환기·산소 유입과 강하게 연결된다는 대비가 핵심이다.')]});
put('F03-C10',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'플레임오버는 2026 소방전술1 기준으로 초기화재에서 대류가 본격적으로 개입해 불꽃이 커지고 벽면에서 천장을 통해 불꽃이 면이동하는 현상이다.',detail:['초기화재에서 대류현상이 본격화되고 불꽃의 크기가 커지면서 벽면에서 천장을 통해 화염이 면이동하는 흐름이 교재의 정의다.','플래시오버는 일정 공간의 가연물이 가열되어 일순간에 동시발화하는 현상이고, 롤오버는 가연성가스가 공기와 만나 부분연소하며 개구부 쪽으로 진행하는 현상이므로 구분한다.','시험에서는 일반적인 표면 화염확산 전체를 플레임오버로 넓혀 외우기보다 공식 교재의 벽면→천장 면이동 표현을 우선 기준으로 삼는다.','교재 40쪽은 플레임오버·플래시오버·백드래프트·롤오버를 같은 핵심요약에서 나란히 구분한다.'],must:['초기화재','대류 본격 개입','벽면 → 천장 불꽃 면이동'],traps:['모든 표면 화염확산을 플레임오버로 일반화하지 않는다','구획실 전체 동시발화는 플래시오버와 구분한다'],compare:[['플레임오버','초기화재·대류·벽면→천장 면이동'],['플래시오버','대류·복사에 의해 공간 내 가연물이 일순간 동시발화'],['롤오버','가연성가스의 부분연소가 개구부 방향으로 진행'],['백드래프트','가연성가스·열 집적 뒤 산소 공급으로 폭발적 발화']],flow:['초기화재','대류 본격화','불꽃 확대','벽면에서 천장으로 면이동'],visuals:['flameover-flow'],source:'2026 소방전술1(화재1) 40쪽',deepSections:[sec('교재 정의','초기화재에서 대류현상이 본격적으로 개입해 불꽃이 커지고 벽면에서 천장을 통해 불꽃이 면이동하는 현상으로 정리한다.'),sec('플래시오버와 비교','플래시오버는 일정 공간의 가연물이 대류·복사에 의해 발화점까지 가열되어 일순간 동시발화하는 현상이다.'),sec('롤오버와 비교','롤오버는 가연성가스가 연소범위에 들어가 공기와 만나 부분적으로 연소하면서 개구부 쪽으로 진행하는 현상이다.'),sec('시험 포인트','플레임오버=초기화재·대류·벽면→천장 면이동이라는 교재 표현을 우선 기억한다.')]});
put('F03-C11',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'백드래프트는 산소가 부족한 밀폐·반밀폐 공간에 고온의 미연소 가스가 축적된 뒤 개구부로 공기가 유입될 때 폭발적으로 연소하는 현상이다.',detail:['환기가 제한되면 화재는 산소 부족으로 약해 보일 수 있지만 내부에는 열과 가연성 열분해가스가 남아 있을 수 있다.','문·창 개방 등으로 신선한 공기가 급격히 들어오면 혼합비가 가연범위에 들어오면서 폭발적 연소가 발생할 수 있다.','외부에서 검게 변한 창, 맥동하는 연기, 틈으로 연기가 들고나는 현상 등은 위험 판단에 참고할 수 있다.'],must:['산소 부족','고온 미연소가스 축적','개구부 개방·공기 유입'],traps:['백드래프트를 단순 열축적만으로 설명하지 않는다','환기 전 위험평가 없이 하부 개구부부터 크게 여는 선택지는 주의'],compare:[['백드래프트','환기 지배·공기 유입·폭발적 연소'],['플래시오버','열 지배·복사열·공간 전체 발화']],flow:['산소소모','불완전연소·가스축적','개구부 형성','공기유입','폭발적 연소'],visuals:['backdraft-flow'],source:'2026 소방전술1 PDF 453쪽',deepSections:[sec('환기 제한 화재','산소가 부족하면 불꽃이 약해 보여도 열과 연료가스가 남아 위험이 사라진 것이 아니다.'),sec('공기 유입의 의미','개구부가 생기면 산소가 연료가스와 섞이며 매우 짧은 시간에 연소조건이 바뀔 수 있다.'),sec('징후 해석','연기 색 하나보다 개구부 상태·연기 움직임·열·공기 유입 징후를 함께 본다.'),sec('시험 포인트','플래시오버와 가장 자주 비교되므로 “열 축적 vs 산소 유입”을 첫 구분축으로 잡는다.')]});
put('F03-C12',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'보일오버는 원유 저장탱크 내부에 물이 존재하는 상태에서 탱크 표면에 화재가 발생해 원유와 물이 함께 탱크 밖으로 흘러넘치는 현상이다.',detail:['교재는 석유류가 혼합된 원유 저장탱크 내부에 외부 유입 또는 자체적으로 생긴 물이 있는 상태를 전제로 설명한다.','탱크 표면 화재가 지속되며 원유와 물이 함께 밖으로 흘러넘치면 인근 저장탱크나 건물로 화염이 확대되어 대규모 화재로 이어질 수 있다.','대처는 저장탱크 외부 냉각과 방제둑 설치 등으로 주변 확산을 최소화하는 방향으로 제시한다.','교재는 저장탱크 외부 냉각과 모래 방제둑 설치를 보일오버의 직접적인 대처방법으로 제시한다.'],must:['원유 저장탱크 내부의 물','탱크 표면 화재','원유와 물이 함께 넘침·화재면 확대'],traps:['연소유 표면에 소화수가 들어가 급비등하는 현상은 슬롭오버와 구분한다','직접적인 화재발생요인이 아닌 뜨거운 점성유체 하부의 물 비등은 프로스오버와 구분한다'],compare:[['보일오버','원유탱크 내부 물+표면화재→원유·물 넘침'],['슬롭오버','뜨거운 유류에 물 접촉→증기팽창·유류 비산'],['프로스오버','뜨거운 점성유체 표면 아래 물 비등→유류 넘침·직접 화재요인 아님']],flow:['탱크 내부 물 존재','탱크 표면 화재','물 비등·유류 거동 확대','원유·물 탱크 밖 넘침','주변 화재확대'],visuals:['tank-overflow-compare'],source:'2026 소방전술1 303쪽',deepSections:[sec('교재 정의','원유 저장탱크 내부에 물이 존재하고 탱크 표면에 화재가 발생하여 원유와 물이 함께 탱크 밖으로 흘러넘치는 현상이다.'),sec('위험성','넘친 원유와 화염이 인근 저장탱크·건물로 확대되어 대규모 화재의 계기가 될 수 있다.'),sec('대처','저장탱크 외부를 냉각하고 모래 등으로 방제둑을 신속히 만들어 주변 확산을 줄인다.'),sec('시험 포인트','보일오버는 원유탱크 내부 물+표면화재, 슬롭오버는 뜨거운 유류와 물의 직접 접촉, 프로스오버는 점성유체 표면 아래 물의 비등으로 나눈다.')]});
put('F03-C13',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'슬롭오버는 물보다 끓는점이 높은 뜨거운 점성 유류에 물이 접촉해 물이 수증기로 팽창·비등하면서 유류를 탱크 밖으로 비산시키는 현상이다.',detail:['교재는 야채를 뜨거운 식용유에 넣었을 때 수분이 비등하며 기름이 튀는 상황을 대표 예로 든다.','소화용수가 연소유의 뜨거운 표면에 유입되는 경우에도 급비등과 부피팽창으로 유류가 외부로 분출될 수 있다.','핵심은 뜨거운 유류와 물의 접촉 및 물의 급격한 수증기 팽창이다.'],must:['뜨거운 점성 유류와 물 접촉','물의 수증기화·부피팽창','유류 외부 비산·분출'],traps:['탱크 내부 물과 표면화재로 원유·물이 함께 넘치는 보일오버와 구분한다','뜨거운 유류 표면 아래 물 비등이 중심인 프로스오버와 구분한다'],compare:[['슬롭오버','뜨거운 유류+물 접촉→수증기팽창·유류비산'],['보일오버','원유탱크 내부 물+표면화재→원유·물 넘침'],['프로스오버','점성유체 표면 아래 물 비등→유류 넘침']],flow:['뜨거운 유류','물 접촉/소화수 유입','물 급비등·수증기 팽창','유류 외부 비산'],visuals:['tank-overflow-compare'],source:'2026 소방전술1 304쪽',deepSections:[sec('교재 정의','물보다 비점이 높은 뜨거운 점성 유류에 물이 닿아 수증기로 팽창·비등하고 유류를 외부로 비산시키는 현상이다.'),sec('대표 사례','소화용수가 연소유의 뜨거운 표면에 들어가 급비등하는 경우가 대표적이다.'),sec('보일오버와 비교','보일오버는 원유탱크 내부 물과 탱크 표면화재가 함께 제시되는 반면 슬롭오버는 뜨거운 유류와 물의 직접 접촉이 중심이다.'),sec('시험 포인트','외부 주수·뜨거운 유류·급비등·비산이 함께 제시되면 슬롭오버를 우선 검토한다.')]});
put('F03-C14',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'프로스오버는 점성을 가진 뜨거운 유류표면 아래의 물이 비등하면서 탱크 내 유류가 넘치는 현상으로, 교재는 직접적인 화재발생요인은 아니라고 설명한다.',detail:['뜨거운 점성 유류의 표면 아래쪽에 존재하는 물이 비등하면서 유류를 위로 밀어 올려 탱크 밖으로 넘치게 한다.','보일오버와 달리 교재는 프로스오버 자체가 직접적인 화재발생요인은 아니라고 명시한다.','시험에서는 물의 위치가 유류표면 아래인지, 탱크 내부 물+표면화재인지, 외부 물 접촉인지로 세 현상을 나누면 안정적이다.'],must:['뜨거운 점성 유류','유류표면 아래 물 비등','탱크 내 유류 넘침','직접적 화재발생요인 아님'],traps:['반드시 탱크 표면화재가 선행한다고 단정하지 않는다','외부 소화수가 뜨거운 유류에 직접 닿는 슬롭오버와 구분한다'],compare:[['프로스오버','점성유체 표면 아래 물 비등·직접 화재요인 아님'],['보일오버','원유탱크 내부 물+표면화재→원유·물 넘침'],['슬롭오버','뜨거운 유류+물 접촉→수증기팽창·유류비산']],flow:['뜨거운 점성 유류','표면 아래 물 비등','수증기 팽창','탱크 내 유류 넘침'],visuals:['tank-overflow-compare'],source:'2026 소방전술1 303쪽',deepSections:[sec('교재 정의','점성을 가진 뜨거운 유류표면 아래 부분의 물이 비등하고 그 힘으로 탱크 내 유류가 넘치는 현상이다.'),sec('화재와의 관계','교재는 프로스오버가 직접적으로 화재발생을 일으키지는 않는다고 설명한다.'),sec('슬롭오버와 비교','프로스오버는 유류표면 아래의 물 비등, 슬롭오버는 뜨거운 유류와 외부 물 접촉이 중심이다.'),sec('시험 포인트','“뜨거운 점성유류 표면 아래 물 비등”과 “직접적 화재발생요인 아님”을 한 묶음으로 기억한다.')]});
put('F03-C15',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'BLEVE는 가압된 액화가스·저비점 액체 용기가 외부화재 등으로 가열되어 압력이 상승하고 용기가 파열되며 액체가 급격히 기화·팽창하는 폭발 현상이다.',detail:['용기 상부 기상부가 화염에 노출되면 금속이 약해지고 내부압력은 올라가 파열위험이 커질 수 있다.','가연성 물질이면 방출된 증기가 점화되어 큰 파이어볼과 강한 복사열이 동반될 수 있다.','폭굉·폭연과는 발생 메커니즘이 다르므로 단순 연소속도 분류와 혼동하지 않는다.'],must:['가압 액체','외부가열·압력상승','용기파열·급격 기화','가연성일 때 파이어볼 가능'],traps:['BLEVE를 가연성 물질에서만 발생 가능한 현상으로 단정하지 않는다','폭굉과 BLEVE를 같은 분류로 보지 않는다'],compare:[['BLEVE','가압 액체 용기 파열+급기화'],['파이어볼','가연성 증기 점화 후 큰 화구'],['폭굉','초음속 충격파 연소전파']],flow:['용기 가열','압력 상승·재질 약화','파열','급격 기화','점화 시 파이어볼'],visuals:['bleve-flow'],source:'2026 소방전술1 PDF 326쪽',deepSections:[sec('용기파열 메커니즘','내부압력 상승과 용기 재질 약화가 동시에 진행되면 파열 가능성이 높아진다.'),sec('파이어볼과 관계','BLEVE 후 방출물질이 가연성이면 점화되어 큰 화구와 복사열이 나타날 수 있다.'),sec('현장위험','용기파편·압력·복사열이 복합 위험을 만들 수 있어 충분한 거리와 냉각·대피 판단이 중요하다.'),sec('시험 포인트','BLEVE 자체와 그 후의 파이어볼을 구분해 묻는 선지가 자주 함정이 된다.')]});
put('F03-C16',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'풀파이어는 누출된 인화성 액체가 바닥이나 방유제 등 일정 면적에 고여 액면 전체가 연소하는 화재다.',detail:['액면에서 생성된 증기가 연소하며 화염과 복사열이 넓은 면적으로 방출될 수 있다.','누출 지속 여부와 풀의 면적은 화재 규모와 복사열 영향에 크게 관여한다.','시험에서는 제트파이어·BLEVE·탱크화재 특수현상과의 차이를 묻기 쉽다.'],must:['누출 액체가 고인 풀','액면 증기 연소','강한 복사열'],traps:['가압가스 분출화염을 풀파이어로 보지 않는다','용기파열 자체를 풀파이어로 보지 않는다'],compare:[['풀파이어','액면 연소'],['제트파이어','가압 누출 제트 연소'],['BLEVE','가압 액체 용기 파열·급기화']],flow:['액체 누출','고임','증기 생성','점화','액면 연소'],visuals:['pool-fire'],source:'2026 소방전술1 PDF 453쪽',deepSections:[sec('연소대상','액체 자체가 아니라 액면 위에서 형성된 가연성 증기가 연소한다.'),sec('복사열','넓은 화염면 때문에 주변 설비와 인명에 복사열 영향을 줄 수 있다.'),sec('확대요인','누출이 계속되거나 방유제가 넘치면 연소면적이 커질 수 있다.'),sec('제트파이어·플래시파이어와 비교','풀파이어는 바닥이나 방유제에 고인 액체의 표면연소가 중심이고, 제트파이어는 압력에 의해 분출되는 가연성 유체의 방향성 화염이 중심이다. 가연성 증기구름이 순간적으로 타고 지나가는 현상과도 연소형태가 다르다.'),sec('시험 포인트','가압분출 중심 제트파이어와 고인 액면 연소인 풀파이어를 구분한다.')]});

put('F07-C16',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'스프링클러설비는 수원·가압송수장치·배관·유수검지장치·헤드·송수구·경보 연동부가 하나의 시스템으로 작동한다.',detail:['헤드만 외우면 작동순서 문제를 풀기 어렵고, 수원에서 헤드까지 물이 이동하는 전체 계통을 이해해야 한다.','밸브류는 평상시 상태와 화재 시 개방 조건이 시스템 방식에 따라 다르다.','압력 또는 유수 변화는 펌프·경보 연동의 단서가 된다.'],must:['수원','가압송수장치','배관·밸브','헤드','경보·송수구'],traps:['헤드가 열리면 펌프나 밸브 관계없이 즉시 모든 구역에 방수된다고 단정하지 않는다','감지기와 헤드의 역할을 혼동하지 않는다'],compare:[['헤드','열을 감지해 방수개구를 형성'],['감지기','화재징후를 전기신호로 검출'],['유수검지장치','유수·압력변화를 검지해 경보 연동']],flow:['수원','펌프','배관·밸브','헤드','화점 방수'],visuals:['sprinkler-system'],source:'2026 예방실무1 PDF 288쪽',deepSections:[sec('전체 계통 이해','스프링클러는 헤드 하나가 아니라 수원·펌프·배관·밸브·헤드·경보가 연계된 자동소화 시스템이다.'),sec('헤드와 감지기','폐쇄형 헤드는 자체 감열부가 열을 받아 개방된다. 준비작동식·일제살수식은 별도 감지설비와 밸브 동작의 관계도 중요하다.'),sec('압력·유수 변화','헤드가 열리고 물이 흐르면 배관 압력·유수 상태가 바뀌며 펌프와 경보장치가 연동된다.'),sec('시험 포인트','구성요소 명칭뿐 아니라 “누가 감지하고, 누가 열리고, 언제 물이 들어오는가” 순서를 묻는 문제에 대비한다.')]});
