const sec=(title,body,bullets=[])=>({title,body,bullets});
const enrich=(id,x)=>{const p=P[id];if(!p)return;p.deepSections=[...(p.deepSections||[]),...(x.deepSections||[])];p.must=[...new Set([...(p.must||[]),...(x.must||[])])];p.traps=[...new Set([...(p.traps||[]),...(x.traps||[])])];p.compare=[...(p.compare||[]),...(x.compare||[])];p.flow=[...new Set([...(p.flow||[]),...(x.flow||[])])];p.visuals=[...new Set([...(p.visuals||[]),...(x.visuals||[])])];if(x.officialLinks){const all=[...(p.officialLinks||[]),...x.officialLinks];p.officialLinks=[...new Map(all.filter(v=>v?.url).map(v=>[v.url,v])).values()]}p.governanceDepth119=true};

enrich('F01-C01',{visuals:['fire-org-chain'],must:['시·도지사 직속→소방본부','소방서장 소속→119안전센터·구조대·구급대 등','설치주체·지휘관계를 분리해서 기억'],traps:['소방본부와 119안전센터를 같은 지휘단계로 묶지 않는다.','소방서장 소속기관을 시·도지사 직속기관으로 바꾼 선지를 주의한다.'],deepSections:[
sec('조직도를 먼저 본다','소방조직 문제는 기관 명칭을 따로 외우기보다 시·도 → 소방본부 → 소방서 → 119안전센터·구조대·구급대 등의 지휘·소속 흐름으로 보면 안정적으로 풀 수 있다.'),
sec('소방본부와 소방서','시·도에서 소방업무를 수행하기 위해 시·도지사 직속으로 소방본부를 두고, 지역 단위 현장업무는 소방서를 중심으로 수행한다. 조직의 설치근거와 지휘·감독 관계를 함께 구분한다.'),
sec('소방서장 소속 하부조직','119안전센터·119구조대·119구급대·119지역대 등은 소방서장 소속으로 둘 수 있다. 시험에서는 “누구 소속인가”를 바꿔 내는 경우가 많다.'),
sec('시험 풀이법','기관명이 나오면 ① 설치단계 ② 지휘·감독 주체 ③ 현장기능을 차례로 확인한다.')]});

enrich('F01-C02',{visuals:['fire-force-triad'],must:['소방력=인력+장비+소방용수','소방력 기준은 업무수행에 필요한 인적·물적 자원 기준'],traps:['소방력을 인원수만 의미한다고 보지 않는다.','소방용수를 소방력 요소에서 빼는 선지를 주의한다.'],compare:[['인력','소방대 등 현장업무 수행 인적자원'],['장비','소방차량·구조구급·통신 등 장비'],['소방용수','화재진압에 필요한 수원']],deepSections:[
sec('소방력의 의미','소방력은 소방업무를 수행할 수 있는 능력을 구성하는 인력·장비·소방용수 등 자원의 총체다. 단순 인원수보다 넓은 개념이다.'),
sec('세 요소를 함께 보는 이유','인력이 충분해도 장비나 용수가 없으면 대응능력이 떨어지고, 장비가 있어도 이를 운용할 인력이 없으면 효과를 내기 어렵다. 세 요소가 함께 작동해야 실제 대응능력이 된다.'),
sec('기준과 배치','소방력 기준은 지역 위험과 업무수요에 맞춰 필요한 인력·차량·장비 등을 갖추기 위한 제도적 기준이라는 관점으로 이해한다.'),
sec('시험 포인트','“소방력=인력만” 또는 “장비만”처럼 범위를 좁힌 선지와 소방용수 포함 여부가 대표 함정이다.')]});

enrich('F01-C03',{visuals:['fire-water-facilities'],must:['소방용수시설 3종=소화전·급수탑·저수조','시·도지사 설치·유지관리'],traps:['비상소화장치를 법정 소방용수시설 3종과 동일한 목록으로 섞지 않는다.','설치·유지관리 주체를 소방서장만으로 바꾼 선지를 주의한다.'],compare:[['소화전','배관계통에서 소방용수 공급'],['급수탑','소방차 등에 급수 지원'],['저수조','필요한 소방용수 저장']],deepSections:[
sec('왜 소방용수가 중요한가','화재진압에서는 장시간 안정적으로 물을 확보할 수 있는지가 현장전술에 직접 영향을 준다. 따라서 소방용수는 소방력의 핵심 요소로 별도 관리된다.'),
sec('법정 3종','소방용수시설은 소화전·급수탑·저수조를 중심으로 기억한다. 각 시설은 물을 얻는 방식은 다르지만 소방활동에 필요한 수원을 제공한다는 공통목적이 있다.'),
sec('설치와 유지관리','설치만 하고 끝나는 것이 아니라 실제 출동 때 사용할 수 있도록 위치·접근성·기능상태를 유지하는 관점이 중요하다.'),
sec('시험 포인트','시설 종류 3종과 설치·관리 주체를 한 문제에서 동시에 바꾸는 선지에 주의한다.')]});

enrich('F01-C04',{visuals:['fire-scene-authority'],must:['소방활동=화재진압·구조·구급 등','소방활동구역 설정→소방대장','생명위험 시 피난명령 권한 구분'],traps:['소방활동구역 설정권자를 일반 관계인으로 바꾸지 않는다.','현장권한을 무제한 권한으로 해석하지 않고 법정 목적·요건과 연결한다.'],compare:[['소방활동','화재진압·인명구조·구급 등 긴급대응'],['소방활동구역','현장 통제와 소방활동 확보'],['피난명령','생명위험 시 일정구역 밖으로 피난 명령']],deepSections:[
sec('현장업무의 목적','소방활동은 불을 끄는 행위만이 아니라 인명구조·구급과 그 밖의 위급상황 대응까지 포함하는 현장활동 개념이다.'),
sec('현장 통제권','소방대장은 소방활동에 필요한 구역을 설정해 불필요한 출입을 제한할 수 있다. 이는 현장 안전과 활동공간 확보를 위한 권한이다.'),
sec('피난명령','사람의 생명에 위험이 있다고 판단되는 상황에서는 법에서 정한 지휘권자가 일정구역 밖으로 피난하도록 명할 수 있다. 권한자와 요건을 묶어 기억한다.'),
sec('시험 포인트','“누가 할 수 있는가”와 “어떤 상황에서 가능한가”를 동시에 묻는 권한형 문제를 대비한다.')]});

enrich('F01-C05',{visuals:['volunteer-fire'],must:['의용소방대=지역 자율 봉사·소방활동 지원','설치·운영은 별도 법률 체계','연합회는 협조·봉사활동 효율화'],traps:['의용소방대를 소방공무원 내부직제와 동일하게 보지 않는다.','자율 봉사조직이라는 성격과 법적 설치·운영 근거를 함께 본다.'],deepSections:[
sec('조직 성격','의용소방대는 지역 주민의 자율적 참여를 바탕으로 소방업무와 재난대응을 지원하는 조직이다. 소방공무원 조직과 동일한 내부직제로 보는 것은 틀리다.'),
sec('지역사회와 역할','평상시 예방·교육·지원활동과 재난 시 소방활동 지원을 통해 지역 대응역량을 보완하는 의미가 있다.'),
sec('연합회','전국 또는 지역 단위 연합회는 의용소방대 상호협조와 자율봉사활동의 효율적 운영을 돕는 역할과 연결된다.'),
sec('시험 포인트','“공무원 조직인가”, “설치·운영 근거는 무엇인가”, “연합회의 목적은 무엇인가”를 구분한다.')]});

enrich('F02-C01',{visuals:['disaster-cycle'],must:['재난=생명·신체·재산·국가에 피해를 주거나 줄 수 있는 상황','자연재난·사회재난 구분','재난관리=예방·대비·대응·복구'],traps:['재난관리를 대응·복구만으로 제한하지 않는다.','사회재난과 자연재난의 대표사례를 뒤바꾸지 않는다.'],compare:[['자연재난','태풍·홍수·대설·한파·지진 등 자연현상'],['사회재난','화재·붕괴·폭발·교통·감염병 확산 등']],deepSections:[
sec('재난의 범위','재난은 이미 피해가 난 경우뿐 아니라 국민의 생명·신체·재산과 국가에 중대한 피해를 줄 수 있는 상황까지 포괄하는 개념으로 이해한다.'),
sec('자연재난과 사회재난','원인이 자연현상인지 사회·기술적 사고나 감염병 등인지에 따라 구분되며, 시험에서는 대표사례를 서로 바꿔 제시한다.'),
sec('재난관리 4단계','예방은 위험을 줄이고, 대비는 자원·계획·훈련을 준비하며, 대응은 발생한 재난에 즉시 조치하고, 복구는 피해를 회복하고 재발방지로 연결한다.'),
sec('순환적 관리','복구에서 얻은 교훈이 다시 예방·대비에 반영되어 다음 재난의 위험을 낮추는 순환체계로 이해하면 단계별 목적이 명확해진다.')]});

enrich('F02-C02',{visuals:['disaster-agency-map'],must:['재난관리책임기관=중앙행정기관·지방자치단체 + 대통령령으로 정하는 기관 등 재난관리업무 수행기관','재난관리주관기관=재난·사고 유형별 예방·대비·대응·복구를 주관하는 관계 중앙행정기관','주관기관의 구체적 유형별 지정=재난안전법 시행령 제3조의2·별표 1의3','책임기관과 주관기관은 포함범위와 역할이 다르다'],traps:['책임기관과 주관기관을 같은 개념으로 보지 않는다.','주관기관을 모든 재난에 대해 하나의 기관으로 고정하지 않는다.','주관기관을 지방자치단체나 일반 공공기관까지 포함하는 넓은 범주로 바꾸지 않는다.','책임기관은 중앙행정기관·지방자치단체만을 뜻한다고 좁혀 외우지 않는다.'],compare:[['재난관리책임기관','재난관리업무를 수행하는 넓은 기관 범주'],['재난관리주관기관','특정 재난·사고 유형을 주관하는 관계 중앙행정기관']],officialLinks:[{label:'재난안전법 제3조 정의',url:'https://www.law.go.kr/lsLawLinkInfo.do?chrClsCd=010202&lsJoLnkSeq=1000808889'},{label:'재난안전법 시행령 제3조·제3조의2',url:'https://www.law.go.kr/LSW/lsLinkCommonInfo.do?lsJoLnkSeq=1031974013'},{label:'시행령 별표 1의3 유형별 주관기관',url:'https://www.law.go.kr/LSW/flDownload.do?bylClsCd=110201&flSeq=153469631'}],deepSections:[
sec('법률 정의부터 구분','재난관리책임기관은 재난관리업무를 하는 기관의 범주이고, 재난관리주관기관은 재난이나 각종 사고의 유형별로 예방·대비·대응·복구 등의 업무를 주관하도록 정해진 관계 중앙행정기관이다. 시험에서는 “누가 넓은 범주인가”와 “누가 유형별 주도기관인가”를 먼저 나눈다.'),
sec('재난관리책임기관의 기본 범위','법 제3조제5호는 중앙행정기관과 지방자치단체를 책임기관에 포함하고, 여기에 지방행정기관·공공기관·공공단체·중요시설 관리기관 등 대통령령으로 정하는 기관을 포함한다. 따라서 책임기관을 중앙정부 기관만으로 좁히면 틀린다.'),
sec('시행령 제3조의 책임기관 범위','중앙행정기관·지방자치단체 외의 책임기관에는 ① 재난관리주관기관 소속 지방행정기관·지정 부속기관 등 ② 위기대응 실무매뉴얼 작성기관 소속 지방행정기관·지정 부속기관 등 ③ 시·도 교육청과 교육지원청 ④ 관계 기관장이 지정하는 소관 공공기관·공공단체 ⑤ 지방자치단체장이 지정하는 소속기관·소관 공공기관·공공단체 ⑥ 중요시설 관리기관 등 지정 기관·단체·법인이 포함된다.'),
sec('지정·고시 절차','시행령 제3조에 따라 일부 책임기관을 지정할 때에는 지정 사실을 고시하고 지정기관의 장과 행정안전부장관에게 통보한다. 중요시설 관리 등 민간 기관·단체·법인을 제3조제1항제6호에 따라 지정하려는 경우에는 해당 민간기관과 행정안전부장관과의 사전 협의가 필요하다.'),
sec('재난관리주관기관의 지정 방식','법 제3조제5호의2와 시행령 제3조의2에 따라 주관기관은 관계 중앙행정기관 중에서 정하고, 실제 어느 기관이 어느 재난·사고를 맡는지는 시행령 별표 1의3에서 유형별로 대응시킨다. 즉 “기관 하나가 모든 재난을 주관”하는 구조가 아니다.'),
sec('둘의 관계를 문제에 적용','책임기관은 각 기관이 자기 소관 재난관리업무를 수행하는 넓은 집합이고, 주관기관은 특정 재난유형에서 예방·대비·대응·복구를 주도하는 중심기관이다. 한 재난 대응에는 주관기관과 여러 책임기관이 함께 참여할 수 있다.'),
sec('시험 직전 판별법','선지에 “관계 중앙행정기관·유형별”이 보이면 주관기관을, “중앙행정기관·지자체·공공기관·공공단체·중요시설 관리기관 등”처럼 범위가 넓게 나오면 책임기관을 먼저 의심한다. 주관기관의 구체적 매칭은 별표 1의3 기준으로 확인한다.')]});

