enrich('F06-C01',{visuals:['fire-investigation-purpose'],must:['화재원인 규명','피해상황 조사','예방·제도개선 활용','관찰사실과 추론 분리'],traps:['화재조사를 책임자 처벌만을 위한 절차로 좁히지 않는다.','확인되지 않은 추정을 사실처럼 기록하지 않는다.'],compare:[['원인조사','발화부·점화원·연소경과 등 원인 규명'],['피해조사','인명·재산·소실범위 등 피해 확인']],deepSections:[
sec('화재조사의 목적','화재조사는 화재가 어디서 어떻게 시작되어 어떻게 확대되었는지와 어떤 피해가 발생했는지를 객관적 자료로 규명하는 활동이다. 결과는 재발방지·예방정책·시설개선·교육 등에 활용된다.'),
sec('원인조사와 피해조사','원인조사는 발화부와 발화원인, 연소확대 경로를 중심으로 보고 피해조사는 인명·재산·소실범위 등 피해결과를 체계적으로 확인한다. 두 영역은 연계되지만 조사목적과 기록항목이 다르다.'),
sec('객관성','조사자의 가설은 필요하지만 사진·흔적·진술·설비상태 등 확인된 사실과 분리해 기록해야 한다. 하나의 단서만으로 결론을 확정하면 오류 위험이 커진다.'),
sec('시험 포인트','“조사의 목적”, “원인조사와 피해조사 구분”, “사실과 추론의 구분”을 묶어 이해하면 단순 암기형과 사례형 모두 대응할 수 있다.')]});

enrich('F06-C02',{visuals:['fire-investigation-process'],must:['현장안전 확보','현장보존','전체→중간→근접 기록','사진·도면·진술 등 다중자료 종합'],traps:['현장 흔적을 기록하기 전에 임의로 이동·폐기하지 않는다.','화재패턴 하나만 보고 발화부를 확정하지 않는다.'],compare:[['관찰','있는 그대로 위치·상태 기록'],['수집','사진·도면·진술·물증 확보'],['분석','자료간 일치·모순 검토'],['결론','근거를 종합해 합리적으로 판단']],deepSections:[
sec('안전이 먼저','조사자는 잔존 화재, 붕괴, 전기, 유해물질 등 위험을 확인하고 안전이 확보된 범위에서 조사한다. 조사과정에서 추가 사고가 발생하면 증거보존도 불가능해진다.'),
sec('현장보존','발화흔적과 연소패턴은 진압·배연·구조·철거 과정에서 쉽게 변형될 수 있다. 필요 이상의 출입·이동·청소를 줄이고 조사 가능한 상태를 유지한다.'),
sec('기록 순서','전체적인 현장관계가 보이는 사진과 도면부터 시작해 중간거리·근접 사진으로 세부흔적을 남기면 나중에 위치관계를 재구성하기 쉽다.'),
sec('다중근거 분석','사진·영상·관계자 진술·전기설비·연소흔적·기상·소방활동 기록 등 서로 다른 자료를 비교해 일치와 모순을 찾는다.'),
sec('오염과 변형을 구분','진압수, 배연, 구조활동, 잔해 이동처럼 화재 이후 현장을 바꾼 행위를 기록해 원래의 연소흔적과 사후 변형을 구분한다. 조사순서는 “안전 확보 → 보존 → 전체 기록 → 세부 관찰·수집 → 분석”으로 잡으면 사례형 문제에서 판단이 흔들리지 않는다.')]});

enrich('F06-C03',{visuals:['fire-origin-cause'],must:['발화부=화재 시작 위치','발화원인=점화가 발생한 원인·과정','점화원+최초착화물+상호작용 검토','가설은 근거로 검증'],traps:['가장 심하게 탄 곳이 항상 발화부라는 단정을 피한다.','점화원이 존재한다는 이유만으로 원인을 확정하지 않는다.'],compare:[['발화부','화재가 처음 시작된 위치 또는 영역'],['점화원','점화에 필요한 에너지원'],['최초착화물','처음 불이 붙은 가연물'],['발화원인','점화원과 가연물·상황이 결합해 발화한 과정']],deepSections:[
sec('발화부 찾기','화재가 시작된 위치를 좁힐 때 연소패턴·소손정도뿐 아니라 환기, 진압수, 붕괴, 연소확대 방향 등 흔적을 변형시킨 요소를 함께 고려한다.'),
sec('발화원인 분석','발화부가 좁혀지면 전기적 아크·불꽃·고온표면·화학반응 등 가능한 점화원과 주변 최초착화물이 실제로 접촉할 수 있었는지 검토한다.'),
sec('가설의 검증','가능한 원인 가설을 여러 개 세우고 각 가설이 현장자료와 일치하는지 검토하며, 설명할 수 없는 모순이 큰 가설은 배제한다.'),
sec('패턴 하나로 결론내리지 않는 이유','환기구 위치, 가연물 배치, 소방활동, 낙하물과 붕괴는 소손 형태를 바꿀 수 있다. 따라서 특정 V자형 흔적이나 가장 심한 탄화만으로 발화부를 고정하지 않고 시간정보·진술·전기설비 상태 등 독립적인 자료와 맞춰 본다.'),
sec('시험 포인트','발화부와 발화원인을 같은 말로 취급하는 선지, 심하게 탄 곳=발화부라고 단정하는 선지가 대표 함정이다.')]});

enrich('F06-C04',{visuals:['fire-damage-record'],must:['인명피해·재산피해 구분','건물·내용물·설비 등 피해대상 구분','사진·도면·목록 등 증빙','조사범위·시점 명확화'],traps:['현장 인상만으로 피해금액·소실범위를 임의 결정하지 않는다.','원인조사 결과와 피해기록이 서로 모순되지 않는지 확인한다.'],compare:[['인명피해','사망·부상 등 사람의 피해'],['재산피해','건물·내용물·설비 등 물적 피해'],['소실범위','연소·열·연기·소방활동 등에 따른 손상범위 기록']],deepSections:[
sec('피해조사의 목적','화재로 발생한 인명·재산 피해를 일관된 기준으로 확인해 통계·보상·예방정책·사후검토 등에 활용할 수 있는 자료를 만드는 과정이다.'),
sec('대상별 분류','건물·수용물·설비 등 피해대상을 구분하고 어느 부분이 연소·열·연기·소방활동 등에 의해 손상되었는지 기록한다.'),
sec('증빙 가능한 기록','사진, 도면, 목록, 현장측정, 관계자료 등 제3자가 다시 확인할 수 있는 근거를 남겨야 한다. 조사시점과 범위가 명확해야 자료 신뢰도가 높다.'),
sec('피해범위를 나눠 기록하는 이유','연소에 직접 소실된 부분, 열·연기에 손상된 부분, 소방활동 과정에서 추가로 손상된 부분을 가능한 범위에서 구분해 기록하면 피해원인과 확대경로를 더 정확히 설명할 수 있다. 금액을 먼저 추정하기보다 대상·범위·근거를 먼저 확정하는 순서가 중요하다.'),
sec('원인조사와 교차검토','피해범위가 추정된 발화부·연소확대 경로와 크게 모순된다면 원인 가설이나 피해기록을 다시 검토해야 한다.')]});

