    {title:'시간당 주입량',formula:'mL/hr = 총량(mL) ÷ 시간(hr)',note:'주입펌프 속도 환산의 기본식.',example:'1000mL를 8시간 → 125mL/hr',evidenceTier:'standard-education-practice'}
